// Loader for the open-source roles: Agent Skills from public repositories (AWS, HashiCorp, Microsoft Playwright,
// Anthropic and MIT-licensed collections), pinned to reviewed commits. The data is server/role-data/roles-opensource.json,
// generated by scripts/build-open-source-roles.mjs; THIRD_PARTY_SKILLS.md lists the sources and licences.
import type { RoleTemplate, SkillSource, SkillTemplate } from './roles.ts';
import data from './role-data/roles-opensource.json' with { type: 'json' };

interface OpenSourceData {
  /** Licence texts by source repository (or repository/skill path when a skill has its own licence file). */
  licenses: Record<string, string>;
  roles: RoleTemplate[];
}

const { licenses, roles } = data as unknown as OpenSourceData;

/** The LICENSE.txt an installed open-source skill carries: where it comes from, what was changed, and its licence. */
export function licenseNotice(name: string, source: SkillSource): string {
  const text = licenses[source.licenseKey];
  if (!text) throw new Error(`No licence text for ${source.licenseKey}`);
  return [
    `The "${name}" skill comes from ${source.repo} (${source.url}),`,
    `commit ${source.commit}, and is licensed under ${source.license}.`,
    '',
    'Agent Portal installs it unchanged, except that the SKILL.md frontmatter is rewritten to the name and',
    'description (other fields, such as allowed-tools, are dropped) and files that would run code are left out.',
    '',
    '----------------------------------------------------------------------',
    '',
    text,
  ].join('\n');
}

const withLicense = (s: SkillTemplate): SkillTemplate => ({
  ...s,
  files: [...(s.files ?? []), { path: 'LICENSE.txt', content: licenseNotice(s.name, s.source!) }],
});

export const OPEN_SOURCE_ROLES: RoleTemplate[] = roles.map((r) => ({ ...r, skills: r.skills.map(withLicense) }));
